    def resolve_district_id(region_slug, district_slug):
        row = db.execute('''SELECT d.id FROM districts d
            JOIN regions r ON r.id=d.region_id
            WHERE r.slug=? AND (d.slug=? OR d.slug LIKE ? OR d.name LIKE ?)''',
            (region_slug, district_slug, f'%{district_slug}%', f'%{district_slug}%')).fetchone()
        return row[0] if row else None

    db.executemany('INSERT OR IGNORE INTO festivals (id,name,description,date_type,source_url) VALUES (?,?,?,?,?)',
                   [(f[0], f[1], f[2], f[3], f[4]) for f in festivals_data])
    db.executemany('''UPDATE festivals SET name=?, description=?, date_type=?, source_url=?
                      WHERE id=?''',
                   [(f[1], f[2], f[3], f[4], f[0]) for f in festivals_data])
    # Consolidate the superseded duplicate Mysuru Dasara record from an earlier Karnataka import.
    db.execute("DELETE FROM festival_districts WHERE festival_id=56")
    db.execute("DELETE FROM festival_months WHERE festival_id=56")
    db.execute("DELETE FROM festival_occurrences WHERE festival_id=56")
    db.execute("DELETE FROM festivals WHERE id=56")

    # Month and district tables are rebuilt from the authoritative tuples so
    # revised festival windows and locations also apply to existing databases.
    for f in festivals_data:
        db.execute('DELETE FROM festival_districts WHERE festival_id=?', (f[0],))
        db.execute('DELETE FROM festival_months WHERE festival_id=?', (f[0],))

    fest_dist_rows = []
    for f in festivals_data:
        fid = f[0]
        for rslug, dslug in f[5]:
            did = resolve_district_id(rslug, dslug)
            if did:
                fest_dist_rows.append((fid, did))
    db.executemany('INSERT OR IGNORE INTO festival_districts (festival_id, district_id) VALUES (?,?)', fest_dist_rows)
    # Bali Yatra belongs in Cuttack; refresh older databases that used the retired Kataka slug.
    bali_yatra = db.execute("SELECT id FROM festivals WHERE name='Bali Yatra'").fetchone()
    cuttack = db.execute("SELECT id FROM districts WHERE slug='cuttack'").fetchone()
    if bali_yatra and cuttack:
        db.execute('DELETE FROM festival_districts WHERE festival_id=?', (bali_yatra[0],))
        db.execute('INSERT OR IGNORE INTO festival_districts (festival_id, district_id) VALUES (?,?)', (bali_yatra[0], cuttack[0]))

    fest_month_rows = []
    for f in festivals_data:
        fid = f[0]
        for m in f[6]:
            fest_month_rows.append((fid, m))
    db.executemany('INSERT OR IGNORE INTO festival_months (festival_id, month) VALUES (?,?)', fest_month_rows)

